package com.logiplatform.model;

import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="transport_plan_legs") public class TransportPlanLeg { @Id @GeneratedValue private UUID id; @Column(name="tenant_id",nullable=false,updatable=false) private UUID tenantId; @Column(name="shipment_id",nullable=false) private UUID shipmentId; @Column(name="sequence_no",nullable=false) private Integer sequenceNo; @Column(nullable=false) private String mode; @Column(name="carrier_name") private String carrierName; @Column(name="carrier_reference") private String carrierReference; @Column(name="origin_code") private String originCode; @Column(name="origin_name") private String originName; @Column(name="destination_code") private String destinationCode; @Column(name="destination_name") private String destinationName; @Column(name="planned_departure") private Instant plannedDeparture; @Column(name="planned_arrival") private Instant plannedArrival; @Column(name="actual_departure") private Instant actualDeparture; @Column(name="actual_arrival") private Instant actualArrival; @Column(nullable=false) private String status="PLANNED"; @Column(name="equipment_type") private String equipmentType; @Column(columnDefinition="text") private String notes; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); protected TransportPlanLeg(){} public TransportPlanLeg(UUID t,UUID s,Integer n,String mode,String carrier,String ref,String oc,String on,String dc,String dn,Instant dep,Instant arr,String equip,String notes){tenantId=t;shipmentId=s;sequenceNo=n;this.mode=mode;carrierName=carrier;carrierReference=ref;originCode=oc;originName=on;destinationCode=dc;destinationName=dn;plannedDeparture=dep;plannedArrival=arr;equipmentType=equip;this.notes=notes;} public UUID getId(){return id;} public UUID getShipmentId(){return shipmentId;} public Integer getSequenceNo(){return sequenceNo;} public String getMode(){return mode;} public String getCarrierName(){return carrierName;} public String getCarrierReference(){return carrierReference;} public String getOriginCode(){return originCode;} public String getOriginName(){return originName;} public String getDestinationCode(){return destinationCode;} public String getDestinationName(){return destinationName;} public Instant getPlannedDeparture(){return plannedDeparture;} public Instant getPlannedArrival(){return plannedArrival;} public String getStatus(){return status;} }
